import pandas as pd


def run(inputs: dict) -> dict:
    target_state = inputs["target_state"].copy()
    cdc_events = inputs["cdc_events"].copy()

    # Build existing state dict from target_state
    existing = {}
    for _, row in target_state.iterrows():
        oid = row["order_id"]
        existing[oid] = {
            "status": row["status"],
            "amount": row["amount"],
            "last_seq": row["last_seq"],
        }

    # Current working state (will be mutated as events applied)
    state = {oid: dict(vals) for oid, vals in existing.items()}

    # Dedupe events by seq (apply-once semantics for at-least-once delivery)
    events_dedup = cdc_events.drop_duplicates(subset="seq", keep="first")
    events_sorted = events_dedup.sort_values("seq", kind="mergesort")

    last_op = {}
    last_applied_seq = {}

    for order_id, group in events_sorted.groupby("order_id", sort=False):
        has_orig = order_id in existing
        orig_last_seq = existing[order_id]["last_seq"] if has_orig else None

        cur_state = dict(existing[order_id]) if has_orig else None
        last_applied_op = None
        last_applied_seq_local = None

        for _, row in group.iterrows():
            seq = row["seq"]

            # Replay guard: based on ORIGINAL target_state last_seq only
            if has_orig and seq <= orig_last_seq:
                continue

            op = row["op"]

            if op == "D":
                if cur_state is None:
                    # D for missing order does nothing
                    continue
                cur_state = None
                last_applied_op = "D"
                last_applied_seq_local = seq
            else:
                # 'I' or 'U'
                if cur_state is None:
                    # create from scratch; amount taken as-is (NULL stays NULL)
                    cur_state = {
                        "status": row["status"],
                        "amount": row["amount"],
                        "last_seq": seq,
                    }
                else:
                    cur_state["status"] = row["status"]
                    if op == "U":
                        if pd.notna(row["amount"]):
                            cur_state["amount"] = row["amount"]
                        # else leave unchanged
                    else:
                        # 'I' always sets amount, including NULL
                        cur_state["amount"] = row["amount"]
                    cur_state["last_seq"] = seq
                last_applied_op = op
                last_applied_seq_local = seq

        if last_applied_op is not None:
            state[order_id] = cur_state  # may be None if deleted
            last_op[order_id] = last_applied_op
            last_applied_seq[order_id] = last_applied_seq_local

    # Build new_state
    new_state_rows = []
    for oid, info in state.items():
        if info is not None:
            new_state_rows.append(
                {
                    "order_id": oid,
                    "status": info["status"],
                    "amount": info["amount"],
                    "last_seq": info["last_seq"],
                }
            )

    new_state = pd.DataFrame(
        new_state_rows, columns=["order_id", "status", "amount", "last_seq"]
    )
    if not new_state.empty:
        new_state = new_state.sort_values("order_id").reset_index(drop=True)

    # Build tombstones: orders whose last applied event in this batch was 'D'
    tomb_rows = []
    for oid, op in last_op.items():
        if op == "D":
            tomb_rows.append(
                {"order_id": oid, "deleted_seq": last_applied_seq[oid]}
            )

    tombstones = pd.DataFrame(tomb_rows, columns=["order_id", "deleted_seq"])
    if not tombstones.empty:
        tombstones = tombstones.sort_values("order_id").reset_index(drop=True)

    return {"new_state": new_state, "tombstones": tombstones}
